package pe.com.dentalamericana.booking;import jakarta.servlet.http.HttpServletRequest;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import pe.com.dentalamericana.appointment.AppointmentRepository;import pe.com.dentalamericana.audit.*;import pe.com.dentalamericana.booking.dto.BookingDtos.*;import pe.com.dentalamericana.common.*;import pe.com.dentalamericana.security.AuthenticatedUser;import pe.com.dentalamericana.user.*;import java.util.List;
@Service public class BookingService{private final PublicBookingRequestRepository requests;private final AppointmentRepository appointments;private final AuditService audit;private final AppUserRepository users;public BookingService(PublicBookingRequestRepository requests,AppointmentRepository appointments,AuditService audit,AppUserRepository users){this.requests=requests;this.appointments=appointments;this.audit=audit;this.users=users;}@Transactional public BookingResponse create(PublicBookingRequestDto r,HttpServletRequest http){PublicBookingRequest b=requests.save(new PublicBookingRequest(trim(r.fullName()),trim(r.documentNumber()),digits(r.mobile()),trim(r.email()),trim(r.service()),r.preferredDate(),r.preferredShift()==null?"INDIFERENTE":r.preferredShift(),trim(r.message())));audit.record(null,"CREAR_SOLICITUD_WEB","SOLICITUD_CITA",b.getId().toString(),AuditResult.EXITO,"Solicitud pública recibida",http);return response(b);}@Transactional(readOnly=true)public List<BookingResponse>list(BookingRequestStatus status){List<PublicBookingRequest>items=status==null?requests.findAllByOrderByCreatedAtDesc():requests.findAllByEstadoOrderByCreatedAtDesc(status);return items.stream().map(this::response).toList();}@Transactional public BookingResponse manage(Long id,ManageBookingRequest r,AuthenticatedUser actor,HttpServletRequest http){PublicBookingRequest b=requests.findById(id).orElseThrow(()->new ResourceNotFoundException("Solicitud no encontrada"));if(!b.getVersion().equals(r.version()))throw new BusinessConflictException("La solicitud fue actualizada por otro usuario");if(r.status()==BookingRequestStatus.AGENDADO){if(r.appointmentId()==null||!appointments.existsById(r.appointmentId()))throw new BusinessConflictException("Para marcar como agendada indique una cita válida");}b.change(r.status(),trim(r.observation()),r.appointmentId(),actor.getId());AppUser u=users.findById(actor.getId()).orElse(null);audit.record(u,"GESTIONAR_SOLICITUD_WEB","SOLICITUD_CITA",id.toString(),AuditResult.EXITO,r.status().name(),http);return response(b);}private BookingResponse response(PublicBookingRequest b){return new BookingResponse(b.getId(),b.getFullName(),b.getDocumentNumber(),b.getMobile(),b.getEmail(),b.getService(),b.getPreferredDate(),b.getPreferredShift(),b.getMessage(),b.getStatus(),b.getInternalObservation(),b.getAppointmentId(),b.getAttendedBy(),b.getCreatedAt(),b.getUpdatedAt(),b.getVersion());}private String trim(String v){return v==null||v.isBlank()?null:v.trim();}private String digits(String v){return v.replaceAll("\\D","");}}
